public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        if (i + 1 >= length) {
            sb.append('\\');
            continue;
        }
        char next = str.charAt(++i);
        switch (next) {
            case 'b':
                sb.append('\b');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\\':
                sb.append('\\');
                break;
            case 'u':
                if (i + 4 >= length) {
                    throw new Exception("Incomplete Unicode escape: \\u");
                }
                String hex = str.substring(i + 1, i + 5);
                int codePoint;
                try {
                    codePoint = Integer.parseInt(hex, 16);
                } catch (NumberFormatException e) {
                    throw new Exception("Invalid Unicode escape: \\u" + hex, e);
                }
                sb.append((char) codePoint);
                i += 4;
                break;
            default:
                if (next >= '0' && next <= '7') {
                    int val = next - '0';
                    int j = i;
                    if (j + 1 < length) {
                        char c1 = str.charAt(j + 1);
                        if (c1 >= '0' && c1 <= '7') {
                            val = val * 8 + (c1 - '0');
                            j++;
                            if (j + 1 < length) {
                                char c2 = str.charAt(j + 1);
                                if (c2 >= '0' && c2 <= '7') {
                                    val = val * 8 + (c2 - '0');
                                    j++;
                                }
                            }
                        }
                    }
                    sb.append((char) val);
                    i = j;
                } else {
                    sb.append(next);
                }
                break;
        }
    }
    return sb.toString();
}

