protected int removeUnusedNodes() {
    int removedCount = 0;
    // Assume the tree root is stored in a field named 'root'.
    if (root == null) {
        return removedCount;
    }
    // Use a stack for iterative depth‑first traversal.
    java.util.ArrayDeque<Category> stack = new java.util.ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        // Create a copy of the children list to avoid concurrent modification.
        java.util.List<Category> children = new java.util.ArrayList<>(current.getChildren());
        for (Category child : children) {
            // Push child onto stack for later processing.
            stack.push(child);
            // If the child is inactive, remove it from its parent.
            if (!child.isActive()) {
                current.removeChild(child);
                removedCount++;
            }
        }
    }
    return removedCount;
}

