final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    // Obtain the offset in the class file buffer where the CONSTANT_Utf8 entry starts.
    int entryOffset = getConstantPoolEntryOffset(constantPoolEntryIndex);
    // The format for a CONSTANT_Utf8 entry is: 
    //   u1   tag (already read by caller)
    //   u2   length
    //   u1[length] bytes of UTF‑8 data
    int length = ((classFileBuffer[entryOffset + 1] & 0xFF) << 8)
               | (classFileBuffer[entryOffset + 2] & 0xFF);
    for (int i = 0; i < length; i++) {
        // Convert each byte directly to a char; callers must ensure
        // that the UTF‑8 sequence is a single byte per character.
        charBuffer[i] = (char) (classFileBuffer[entryOffset + 3 + i] & 0xFF);
    }
    return new String(charBuffer, 0, length);
}

