private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }
    int running = 0;
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffix.set(i, running);
    }
    long total = 0;
    for (int val : bounds) {
        total += val;
    }
    return new Pair<>(suffix, total);
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list.head == null || list == this){
        return;
    }
    if (this.head == null){
        this.head = list.head;
        this.tail = list.tail;
        this.size += list.size;
    } else {
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
        this.size += list.size;
    }
    list.head = null;
    list.tail = null;
    list.size = 0;
}

