public static String applyRelativePath(String path,String relativePath){
    // Find base directory (parent of the given path)
    String baseDir;
    int lastSlash = path.lastIndexOf('/');
    if(lastSlash == -1){
        baseDir = "";
    }else{
        baseDir = path.substring(0,lastSlash);
    }
    // Determine if original path is absolute (starts with '/')
    boolean isAbsolute = path.startsWith("/");
    // Split base directory into parts (ignore empty segments)
    List<String> parts = new ArrayList<>();
    for(String part : baseDir.split("/")){
        if(!part.isEmpty()){
            parts.add(part);
        }
    }
    // Process relative path components
    if(relativePath != null){
        for(String seg : relativePath.split("/")){
            if(seg.isEmpty() || seg.equals(".")){
                // no-op
                continue;
            }else if(seg.equals("..")){
                if(!parts.isEmpty()){
                    parts.remove(parts.size()-1);
                }else{
                    // at root, keep root
                }
            }else{
                parts.add(seg);
            }
        }
    }
    // Build final path string
    StringBuilder result = new StringBuilder();
    if(isAbsolute){
        result.append('/');
    }
    // Join parts with '/'
    for(int i=0;i<parts.size();i++){
        if(i>0) result.append('/');
        result.append(parts.get(i));
    }
    return result.toString();
}

static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return new String[0];
    }
    int nonNullCount = 0;
    for (Object o : array) {
        if (o != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        return (String[]) array;
    }
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

